/**
 * Proves that no question the app can ask is invalid.
 *
 * Run with `npm run sentences:check`. Reads the shipped packs and the decks
 * they were built against, and re-asks, of every sentence, the question the
 * pipeline is supposed to have asked: does this sentence use this word, with
 * this reading?
 *
 * A second implementation would be worth more than a re-run of the same code,
 * and this is not one — it shares `lib/reading-check.mjs` with the builder. It
 * is still worth having. The packs are committed artefacts: they can be edited,
 * regenerated by an older checkout, or left behind by a deck change that never
 * rebuilt them, and none of those show up in a diff anyone reads. This says so
 * in one line.
 *
 * Exits non-zero on any failure, so it can stand beside the tests rather than
 * being something to remember.
 */
import { existsSync, readdirSync, readFileSync } from 'node:fs';
import { dirname, resolve } from 'node:path';
import { fileURLToPath } from 'node:url';
import { createTokenizer, usesWord } from './lib/reading-check.mjs';
import { ambiguousHeadwords, confirms, contradicts, readIndices } from './lib/tatoeba-index.mjs';

const ROOT = resolve(dirname(fileURLToPath(import.meta.url)), '..');
const DECKS = resolve(ROOT, 'public/decks');
const PACKS = resolve(ROOT, 'public/sentences');
const INDEX_CSV = resolve(ROOT, 'data/tatoeba/jpn_indices.csv');

const tokenizer = await createTokenizer();

/*
 * The annotators' veto, when their file is present.
 *
 * It is 17 MB of raw corpus and lives in `data/tatoeba/`, which is not
 * committed — so a fresh checkout can check the packs without it and a machine
 * that has run `npm run sentences` gets the stricter check. Saying which of the
 * two ran matters more than quietly doing less.
 */
const indices = existsSync(INDEX_CSV) ? readIndices() : null;
const ambiguous = indices ? ambiguousHeadwords(indices) : new Set();

let pairs = 0;
let withSentences = 0;
let items = 0;
const problems = [];

for (const file of readdirSync(DECKS)) {
  if (!file.startsWith('vocab-')) continue;

  const deck = JSON.parse(readFileSync(resolve(DECKS, file), 'utf8'));
  const pack = JSON.parse(readFileSync(resolve(PACKS, file), 'utf8'));
  const byId = new Map(deck.items.map((item) => [item.id, item]));

  // A key with no item behind it is a pack built against a different deck.
  for (const id of Object.keys(pack.sentences)) {
    if (!byId.has(id)) problems.push(`${file}: pack has "${id}", which is not in the deck`);
  }

  for (const item of deck.items) {
    items += 1;
    const sentences = pack.sentences[item.id];
    if (!sentences || sentences.length === 0) continue;

    withSentences += 1;

    for (const sentence of sentences) {
      pairs += 1;

      if (!sentence.text.includes(item.word)) {
        problems.push(`${item.id}: sentence ${sentence.id} does not contain ${item.word}`);
        continue;
      }

      if (!usesWord(tokenizer, sentence.text, item.word, item.reading)) {
        problems.push(
          `${item.id}: "${sentence.text}" does not use ${item.word} read ${item.reading}`,
        );
        continue;
      }

      if (!indices) continue;

      if (ambiguous.has(item.word)) {
        // A word the corpus reads two ways has to be confirmed, not merely
        // left uncontradicted.
        if (!confirms(indices, sentence.id, item.word, item.reading)) {
          problems.push(
            `${item.id}: "${sentence.text}" — ${item.word} is read more than one way and the ` +
              `index does not confirm ${item.reading} here`,
          );
        }
      } else if (contradicts(indices, sentence.id, item.word, item.reading)) {
        problems.push(
          `${item.id}: "${sentence.text}" — Tatoeba's index reads ${item.word} differently here`,
        );
      }
    }

    // Attribution is a licence term, not a nicety: CC-BY 2.0 FR.
    for (const sentence of sentences) {
      if (!Number.isInteger(sentence.id)) {
        problems.push(`${item.id}: a sentence has no Tatoeba id to attribute it by`);
      }
    }
  }
}

console.log(
  indices
    ? `checked with kuromoji and Tatoeba's index of ${indices.size} sentences`
    : "checked with kuromoji only — data/tatoeba/jpn_indices.csv is absent, so the annotators' veto did not run",
);
console.log(`${items} vocabulary entries, ${withSentences} with at least one sentence`);
console.log(`${pairs} word/sentence pairs checked`);

if (problems.length === 0) {
  console.log('\nEvery sentence uses its word with its reading. No invalid questions.');
  process.exit(0);
}

console.error(`\n${problems.length} invalid question(s):\n`);
for (const problem of problems.slice(0, 40)) console.error(`  ${problem}`);
if (problems.length > 40) console.error(`  …and ${problems.length - 40} more`);
process.exit(1);
